const { PDFDocument, rgb } = require('pdf-lib');
const fontkit = require('@pdf-lib/fontkit');
const fs = require('fs');

(async () => {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const font = await doc.embedFont(fs.readFileSync('/usr/share/fonts/workspacex/NotoSansSC-Common.otf'));

  const W = 595, H = 842;
  const LM = 50, RM = 50, TM = 60;
  const contentW = W - LM - RM;

  // Helper: draw wrapped Chinese text, returns next y
  function drawWrapped(page, text, x, y, size, opts = {}) {
    const maxChars = Math.floor(contentW / size);
    let curY = y;
    for (let i = 0; i < text.length; i += maxChars) {
      const chunk = text.slice(i, i + maxChars);
      page.drawText(chunk, { x, y: curY, size, font, ...opts });
      curY -= size * 1.6;
    }
    return curY;
  }

  // --- Page 1 ---
  const p1 = doc.addPage([W, H]);
  let y = H - TM;

  // Title
  p1.drawText('AI 助手能力总览', { x: LM, y, size: 28, font, color: rgb(0.12, 0.28, 0.55) });
  y -= 45;
  p1.drawLine({ start: { x: LM, y }, end: { x: W - RM, y }, thickness: 1.2, color: rgb(0.12, 0.28, 0.55) });
  y -= 30;

  const intro = '以下是我当前可以为您提供的核心能力，涵盖文档处理、数据分析、研究调研、会议协作、可视化及自动化等多个领域。';
  y = drawWrapped(p1, intro, LM, y, 12);
  y -= 15;

  const sections = [
    { title: '1. 文档创建与处理', items: [
      '生成 PDF、Word (.docx)、Excel (.xlsx)、PowerPoint (.pptx) 文件',
      '读取并理解上传的 PDF、Office、CSV 文件内容',
      '对已有 Office 文件进行有限的文本替换编辑',
      '填写标准 PDF 表单域（AcroForm）'
    ]},
    { title: '2. 数据分析与可视化', items: [
      '分析 CSV / XLSX / JSON 数据，给出可复现的计算与结论',
      '生成静态图表（柱状图、折线图、饼图等），校验中文标签与单位',
      '数据质量说明与缺失值处理'
    ]},
    { title: '3. 研究与知识问答', items: [
      '联网搜索公开信息，形成带引用的研究报告',
      '基于组织内部资料回答政策、项目知识问题（附出处）',
      '综合多场访谈记录，提炼主题、引文与反例'
    ]},
    { title: '4. 会议与沟通协作', items: [
      '将会议转录整理为决策与行动项纪要',
      '准备会议背景材料、议程与预读文档',
      '撰写内部公告、领导更新、FAQ、周报等沟通草稿',
      '根据项目状态生成里程碑或领导简报'
    ]}
  ];

  for (const sec of sections) {
    y -= 8;
    p1.drawText(sec.title, { x: LM, y, size: 15, font, color: rgb(0.15, 0.35, 0.65) });
    y -= 22;
    for (const item of sec.items) {
      const bullet = '• ' + item;
      y = drawWrapped(p1, bullet, LM + 10, y, 11);
      y -= 2;
    }
    y -= 6;
  }

  // --- Page 2 ---
  const p2 = doc.addPage([W, H]);
  y = H - TM;

  p2.drawText('AI 助手能力总览（续）', { x: LM, y, size: 22, font, color: rgb(0.12, 0.28, 0.55) });
  y -= 40;
  p2.drawLine({ start: { x: LM, y }, end: { x: W - RM, y }, thickness: 1, color: rgb(0.12, 0.28, 0.55) });
  y -= 25;

  const sections2 = [
    { title: '5. 用户研究与规划', items: [
      '将研究目标转成研究计划、招募条件与中立访谈提纲',
      '把需求讨论提炼为 MAAU（最小智能体可执行单元）画布'
    ]},
    { title: '6. 视觉内容与网页产物', items: [
      '为海报、配图确定构图与文案，生成图片或精确排版',
      '创建自包含交互式网页产物（响应式布局、状态管理）',
      '整理和修改 Mermaid / 画布 Markdown 源码'
    ]},
    { title: '7. 音频与转录', items: [
      '将授权音频转录为可审阅文本，保留时间范围标注',
      '支持最长 60 分钟内部会议转录的结构化处理'
    ]},
    { title: '8. 技能编写与自动化', items: [
      '将重复工作流程整理为可复用的技能草稿包',
      '在沙箱中执行 Shell 命令、Python / Node.js 脚本',
      '文件系统操作：读写、搜索、批量处理'
    ]}
  ];

  for (const sec of sections2) {
    y -= 8;
    p2.drawText(sec.title, { x: LM, y, size: 15, font, color: rgb(0.15, 0.35, 0.65) });
    y -= 22;
    for (const item of sec.items) {
      const bullet = '• ' + item;
      y = drawWrapped(p2, bullet, LM + 10, y, 11);
      y -= 2;
    }
    y -= 6;
  }

  // Footer note
  y -= 20;
  p2.drawLine({ start: { x: LM, y }, end: { x: W - RM, y }, thickness: 0.5, color: rgb(0.6, 0.6, 0.6) });
  y -= 18;
  const note = '注：以上能力依赖当前沙箱环境中预装的库与字体。部分高级功能（如 OCR、数字签名、PDF 合并拆分）暂不支持。如需了解具体能力的边界或限制，请随时询问。';
  y = drawWrapped(p2, note, LM, y, 10, { color: rgb(0.4, 0.4, 0.4) });

  const bytes = await doc.save();
  fs.writeFileSync('/workspace/ai-capabilities-summary.pdf', bytes);
  console.log('PDF generated successfully.');
})().catch(e => { console.error(e.stack); process.exit(1); });
